const j = $input.first().json;
const COMPACT = "
FORMATO DE SAÍDA OBRIGATÓRIO (substitui qualquer formato anterior): NÃO responda JSON. Responda SOMENTE linhas de texto, uma por lançamento, no formato:
DD/MM/YYYY|descricao|valor|sinal|categoria|parcela
- valor com ponto decimal e sem R$ (ex: 1234.56)
- sinal: + para entrada, - para saída
- parcela: XX/YY ou vazio
Sem cabeçalho, sem cercas de código, sem comentários, sem linhas extras.";
const model = "anthropic/claude-sonnet-4.5", perPage = false, compact = false, maxTok = 32768;
const post = compact ? j.postHead + COMPACT : j.postJson;
const head = j.pages[0].slice(0, 1500);
if (!perPage) {
  const prompt = j.pre + 'O arquivo está aqui:
' + JSON.stringify(j.pages, null, 2) + '

' + post;
  return [{ json: { model, max_tokens: maxTok, prompt } }];
}
return j.pages.map((p, i) => ({ json: { model, max_tokens: maxTok, prompt:
  j.pre + 'CABEÇALHO DA FATURA (apenas contexto para datas/vencimento — NÃO extraia lançamentos daqui):
' + head +
  '

O arquivo está aqui (PÁGINA ' + (i + 1) + ' de ' + j.pages.length + ' — extraia SOMENTE os lançamentos desta página; se não houver, responda vazio):
' + p + '

' + post } }));

const rs = $input.all();
const base = $('Dados').first().json;
const isJson = true;
let tx = 0, sum = 0, pt = 0, ct = 0, erros = 0;
for (const r of rs) {
  const c = (r.json.choices && r.json.choices[0] && r.json.choices[0].message.content) || '';
  pt += (r.json.usage || {}).prompt_tokens || 0; ct += (r.json.usage || {}).completion_tokens || 0;
  if (isJson) {
    try { const m = c.match(/\{[\s\S]*\}/); const arr = JSON.parse(m[0]).output; tx += arr.length; sum += arr.reduce((a, t) => a + Math.abs(Number(t.v) || 0), 0); } catch (e) { erros++; }
  } else {
    for (const l of c.split('\n')) { const f = l.split('|'); if (f.length >= 5 && /\d{2}\/\d{2}/.test(f[0])) { tx++; sum += Math.abs(parseFloat(f[2]) || 0); } }
  }
}
return [{ json: { variante: "A - Sonnet 4.5 JSON 1 chamada (atual)", doc: base.doc, chamadas: rs.length, lancamentos: tx, soma: Math.round(sum * 100) / 100, baseline_lancamentos: base.baseline_count, baseline_soma: base.baseline_sum, tokens_entrada: pt, tokens_saida: ct, erros_parse: erros } }];

